<?php $user=require_auth(); $pageTitle='Мои сборки'; $stmt=db()->prepare('SELECT * FROM builds WHERE user_id=? ORDER BY created_at DESC'); $stmt->execute([$user['id']]); $builds=$stmt->fetchAll(); require __DIR__.'/../includes/header.php'; ?><section class="page-heading inline"><div><p class="eyebrow">SAVED BUILDS</p><h1>Мои сборки</h1></div><a class="primary-btn" href="?page=configurator">Новая сборка <span>↗</span></a></section><div class="builds-grid"><?php if(!$builds): ?><div class="empty-state"><span>◈</span><h2>Пока пусто</h2><p>Соберите первый ПК в конфигураторе.</p><a href="?page=configurator">Открыть конфигуратор →</a></div><?php endif; ?><?php foreach($builds as $build): $items=json_decode($build['components_json'],true) ?: []; ?><article class="saved-build"><div class="saved-top"><span class="eyebrow">BUILD #<?= (int)$build['id'] ?></span><span><?= date('d.m.Y',strtotime($build['created_at'])) ?></span></div><h2><?= e($build['name']) ?></h2><div class="saved-items"><?php foreach($items as $item): ?><span><?= e($item['name']) ?></span><?php endforeach; ?></div><strong class="saved-price"><?= number_format((float)$build['total_price'],0,',',' ') ?> ₽</strong></article><?php endforeach; ?></div><?php require __DIR__.'/../includes/footer.php';
